/*
 * Fuzz harness for nDPI's protocol configuration file parser.
 * Targets load_protocols_file_fd() - the file descriptor-based
 * protocol definition loader.
 *
 * Follows the same pattern as other fuzz_filecfg_*.c fuzzers in
 * the nDPI project.
 */
#include "ndpi_api.h"
#include "ndpi_private.h"
#include "fuzz_common_code.h"

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  struct ndpi_detection_module_struct *ndpi_struct;
  FILE *fd;

  /* To allow memory allocation failures */
  fuzz_set_alloc_callbacks_and_seed(size);

  ndpi_struct = ndpi_init_detection_module(NULL);
  if(!ndpi_struct)
    return 0;

  ndpi_set_config(ndpi_struct, NULL, "log.level", "3");
  ndpi_set_config(ndpi_struct, "all", "log", "1");

  fd = buffer_to_file(data, size);
  load_protocols_file_fd(ndpi_struct, fd);
  if(fd)
    fclose(fd);

  ndpi_exit_detection_module(ndpi_struct);
  return 0;
}
